tool_b.code_example:
# Auth0 prices the tier, not the user: 501 MAU bills as 1,000.
TIERS = [(500, 35), (1_000, 70), (2_500, 175), (5_000, 350)]
def essentials(mau):
    return next(p for cap, p in TIERS if mau <= cap)
print(essentials(501))  # 70, not 35
